/* Mind maps for every NISM V-A chapter (March 2026 workbook). Generated from indented outlines; each node is {n: label, c: children}. */
window.MAPS=[{"id":"ch1","n":1,"marks":8,"title":"Investment Landscape","sub":"Goals, compounding, the four asset classes, every risk type, behavioural biases, risk profiling and asset allocation.","root":{"n":"Investment Landscape","c":[{"n":"Goals and time value","c":[{"n":"Financial goal = objective + amount + timeline"},{"n":"Hospitalisation, theft, fire: emergency fund + insurance, not investments"},{"n":"Pool approach flaw: horizon unknown"},{"n":"Compounding (workbook numbers)","c":[{"n":"Shalini: Rs 50 lakh at 8% for 10 yrs = Rs 1,07,94,625"},{"n":"Rs 30,000 at 6%","c":[{"n":"1 yr: 31,800"},{"n":"10 yrs: 53,725"},{"n":"20 yrs: 96,214"}]},{"n":"Rs 10,000 at 8%","c":[{"n":"5 yrs: 14,693"},{"n":"10 yrs: 21,589"},{"n":"20 yrs: 46,610"},{"n":"30 yrs: 1,00,627"}]}]},{"n":"Inflation erodes buying power","c":[{"n":"100 units buys 68 after 5 yrs, 46 after 10"},{"n":"Nominal = before inflation"},{"n":"Real = after inflation"}]}]},{"n":"Saving vs investing","c":[{"n":"Saving precedes investing (\"saving\" comes from \"safe\")"},{"n":"Top 3 evaluation factors: safety, liquidity, returns"},{"n":"Exit penalty hits returns, not liquidity"},{"n":"A mutual fund is a different way of investing, not a different product"}]},{"n":"Asset classes","c":[{"n":"Real estate","c":[{"n":"Location is key"},{"n":"Illiquid and not divisible"},{"n":"Self-occupied home = expense, not investment"}]},{"n":"Commodities","c":[{"n":"Only class with no intermittent cash flow"},{"n":"Physical gold = no regular income"},{"n":"Commodity derivatives aren't investments: leveraged + short-term"}]},{"n":"Equity","c":[{"n":"Sensex: base 100 in 1979"},{"n":"82,269 by 30 Jan 2026, ~15.4% p.a. (before dividends)"},{"n":"Listed equity is liquid but unfit for short-term needs"}]},{"n":"Fixed income","c":[{"n":"Bond bought at issue, held to maturity: no capital gain"},{"n":"Own government's bonds = safest, lowest rate"}]},{"n":"Only financial form: equity and bonds"},{"n":"Table 1.1 mapping","c":[{"n":"Fixed income: PPF, SSY, SCSS, POMIS, endowment / money-back"},{"n":"Real estate: REITs, InvITs, REMF"},{"n":"Others: coins, art, stamps"}]}]},{"n":"Risks","c":[{"n":"Inflation risk"},{"n":"Liquidity risk"},{"n":"Credit risk","c":[{"n":"Cause: borrower's ability or intention to pay"},{"n":"Measured by rating + spreads"}]},{"n":"Market vs specific risk","c":[{"n":"Market-wide risk cannot be diversified"},{"n":"Company / industry-specific risk can (pager = industry-specific)"}]},{"n":"Interest rate risk","c":[{"n":"Rates up, bond price down"},{"n":"Longer maturity = bigger swing"}]},{"n":"Managing risk","c":[{"n":"Avoid, take a position, or diversify"},{"n":"Lay investor: diversify"}]},{"n":"Measuring volatility","c":[{"n":"Variance, standard deviation, beta, modified duration"}]}]},{"n":"Behavioural biases","c":[{"n":"Dominant emotions: fear, greed, hope"},{"n":"Loss aversion: Rs 5,000 loss hurts more than gain (Kahneman & Tversky)"},{"n":"Confirmation bias: decide first, seek proof later"},{"n":"Familiarity bias: \"known devil vs unknown angel\""},{"n":"Recency bias: bull run drives over-allocation"},{"n":"Interest of the investor: IT employee holds only tech stocks"},{"n":"Remedy: third opinion from an RIA or MFD"}]},{"n":"Risk profile","c":[{"n":"Need + ability + willingness"},{"n":"Ability = finances + horizon"},{"n":"Willingness = psychology"}]},{"n":"Asset allocation","c":[{"n":"Strategic: fixed target mix"},{"n":"Tactical / dynamic","c":[{"n":"Aims to improve risk-adjusted return"},{"n":"For seasoned investors with large surplus"}]},{"n":"Rebalancing","c":[{"n":"Sell what rose, buy what fell"},{"n":"50:50, A +20%, B −5% on Rs 1,000 each: sell Rs 125 of A"}]},{"n":"Passive breach of scheme allocation","c":[{"n":"Rebalance within 30 business days"},{"n":"Excludes index funds / ETFs"},{"n":"Not applicable to overnight funds"}]}]},{"n":"DIY vs professional help","c":[{"n":"DIY hidden costs: time + mistakes"},{"n":"2% fee on Rs 10 lakh = ~Rs 20,000 a year"}]}]}},{"id":"ch2","n":2,"marks":6,"title":"Concept and Role of a Mutual Fund","sub":"Key terms, pros and cons, open vs close-ended, every SEBI 2026 category with its limits, other fund types and SIF.","root":{"n":"Concept and Role of a Mutual Fund","c":[{"n":"Concept and role","c":[{"n":"Invest through an MF, not in it"},{"n":"Set up as a trust"},{"n":"Profits and losses belong only to unitholders"},{"n":"Everyone else earns a fee or commission"},{"n":"Market stabiliser: MF inflows countered FPI selling in 2022 and 2025"},{"n":"Each pool = a scheme with a pre-announced investment objective"},{"n":"Investment policy = asset allocation + investment style (in the SID)"}]},{"n":"Key terms","c":[{"n":"Face value: typically Rs 10 (can be Rs 100)"},{"n":"Unit capital = units × face value"},{"n":"AUM = NAV × units outstanding; AMCs ranked by AUM"},{"n":"NAV = net realisable value per unit if liquidated"},{"n":"Mark to market: each security valued at market price daily"},{"n":"IDCW = Income Distribution cum Capital Withdrawal (was dividend)"},{"n":"Recurring expenses: % of AUM, lower the NAV"}]},{"n":"Advantages","c":[{"n":"Diversification from Rs 500"},{"n":"Professional management and economies of scale"},{"n":"Transparency: SID, SAI, KIM, portfolio, NAV (even for prospective investors)"},{"n":"Tax deferral: MF pays no tax; growth option defers tax"},{"n":"ELSS: Sec 80C up to Rs 1,50,000, Old Tax Regime only"},{"n":"Systematic plans","c":[{"n":"SIP: invest"},{"n":"SWP: withdraw"},{"n":"STP: transfer"}]}]},{"n":"Limitations","c":[{"n":"No customisation (PMS gives it)"},{"n":"Choice overload (answer: SEBI categorisation)"},{"n":"No control over costs"},{"n":"No guaranteed returns"},{"n":"Pass-through vehicle: manager controls only his own skill"}]},{"n":"Structure","c":[{"n":"Open-ended","c":[{"n":"Buy / sell any time after NFO"},{"n":"Unit capital keeps changing"}]},{"n":"Close-ended","c":[{"n":"Buy only in NFO; fixed maturity"},{"n":"Compulsorily listed (except ELSS)"},{"n":"Unit capital fixed"},{"n":"Usually trades at a discount to NAV"}]},{"n":"Interval fund","c":[{"n":"Close-ended, opens at intervals; listed"},{"n":"Transaction period min 2 days"},{"n":"Interval period 15 days (workbook)"}]},{"n":"ETF","c":[{"n":"Trades all day at multiple prices"},{"n":"Needs a demat account; tracks NAV closely"},{"n":"Silver ETF now allowed"}]},{"n":"Active vs passive","c":[{"n":"Active: higher cost, aims to beat the market"},{"n":"Passive / index: tracks index, low cost"}]},{"n":"MF Lite","c":[{"n":"Chapter X of MF Regulations 2026"},{"n":"Lighter framework for passive schemes only (index, ETF, FoF)"}]}]},{"n":"SEBI categories (2026)","c":[{"n":"5 categories: Equity 13, Debt 17, Hybrid 7, Life Cycle, Other 2"},{"n":"Market cap: Large 1–100, Mid 101–250, Small 251+ (full market cap)"},{"n":"Equity (13)","c":[{"n":"Multi cap: ≥75% equity, ≥25% each large, mid, small"},{"n":"Large cap: 80%"},{"n":"Large & Mid: 35% + 35%"},{"n":"Mid cap: 65%"},{"n":"Small cap: 65%"},{"n":"Dividend yield: 80%"},{"n":"Value: 80%"},{"n":"Contra: 80% (AMC can offer both value and contra if overlap ≤50%)"},{"n":"Focused: max 30 stocks, 80%"},{"n":"Sectoral: 80%"},{"n":"Thematic: 80% (overlap ≤50% with other schemes, except large cap)"},{"n":"ELSS – Tax Saver Fund: 80% + 3-year lock-in"},{"n":"Flexi cap: 65%, any mix"},{"n":"Residual: money market, gold and silver, InvITs"}]},{"n":"Debt (17)","c":[{"n":"Overnight: 1 day (≤5% in G-secs / T-bills ≤30 days for margin)"},{"n":"Liquid: up to 91 days"},{"n":"Ultra-Short-Term: 3–6 months Macaulay"},{"n":"Ultra Short to Short Term: 6–12 months (was low duration)"},{"n":"Money market: up to 1 year"},{"n":"Short Term: 1–3 yrs"},{"n":"Medium Term: 3–4 yrs"},{"n":"Medium to Long Term: 4–7 yrs"},{"n":"Long Term: >7 yrs"},{"n":"Dynamic Term: any duration"},{"n":"Corporate bond: 80% in AA+ and above"},{"n":"Credit risk: 65% in AA and below (AA+ excluded); no \"high yield\" names"},{"n":"Banking and PSU Debt: 80%"},{"n":"Gilt: 80% G-secs"},{"n":"10-year constant maturity Gilt: 80%, duration = 10 yrs"},{"n":"Floating Interest Rates Fund: 65%"},{"n":"Sectoral debt: 80% in one sector, AA+ and above only","c":[{"n":"Financial Services, Energy, Infrastructure, Housing, Real Estate"}]}]},{"n":"Hybrid (7)","c":[{"n":"Conservative: debt 75–90%, equity 10–25%"},{"n":"Balanced: equity 40–60%, no arbitrage"},{"n":"Aggressive: equity 65–80%"},{"n":"Balanced Advantage: dynamic equity / debt"},{"n":"Multi asset: ≥3 asset classes, ≥10% each (foreign not a separate class)"},{"n":"Arbitrage: 65% equity; debt only G-secs <1 yr and G-sec repo"},{"n":"Equity savings: 65% equity + 10% debt; net equity 15–40%"},{"n":"Residual: InvITs (not arbitrage), ETCDs, gold and silver ETFs"}]},{"n":"Life Cycle Funds","c":[{"n":"Glide path: equity falls, debt rises near maturity"},{"n":"Tenure 5–30 yrs, in multiples of 5"},{"n":"Max 6 open for subscription per MF"},{"n":"15-yr example (equity / debt)","c":[{"n":"10–15 yrs left: 65–80 / 5–25"},{"n":"5–10 yrs: 50–65 / 5–25"},{"n":"3–5 yrs: 35–50 / 25–50"},{"n":"1–3 yrs: 20–35 / 25–65"},{"n":"<1 yr: 5–20 / 25–65"}]}]},{"n":"Other (2)","c":[{"n":"Index fund / ETF: 95% in index securities"},{"n":"FoF: 95% in underlying fund"}]},{"n":"One scheme per category, except","c":[{"n":"Index funds / ETFs on different indices"},{"n":"FoFs with different underlyings"},{"n":"Sector / thematic on different sectors"}]}]},{"n":"Other fund types","c":[{"n":"FMP: close-ended debt; returns clearer, not guaranteed"},{"n":"Target Maturity Fund: 2–14 yrs, listed, cuts reinvestment risk"},{"n":"Capital protection: Rs 90 in debt grows to Rs 100, rest in equity derivatives"},{"n":"IDF: close-ended, ≥90% infra debt","c":[{"n":"IDF-MF: sponsored by banks and NBFCs"},{"n":"IDF-NBFC: banks and IFCs only"}]},{"n":"REMF: SEBI circular 2 May 2008 cities; close-ended, listed"},{"n":"REITs / InvITs: not MF schemes","c":[{"n":"Assets ≥ Rs 500 cr, offer ≥ Rs 250 cr"},{"n":"Min lot Rs 10,000–15,000; traded lot 1 unit"}]},{"n":"ESG: under thematic","c":[{"n":"Exclusion, integration, best-in-class, impact, sustainable objectives, transition"}]},{"n":"Smart beta: index-based, not market-cap weighted"},{"n":"Quant fund: model-driven, removes the human element"}]},{"n":"Specialised Investment Fund (SIF)","c":[{"n":"Gap between MF and PMS"},{"n":"Min Rs 10 lakh across strategies of the same AMC"},{"n":"Max 25% unhedged short exposure; one strategy per category"},{"n":"Equity","c":[{"n":"Long-Short: ≥80% equity"},{"n":"Ex-Top 100: ≥65%"},{"n":"Sector Rotation: ≥80%, max 4 sectors"},{"n":"Redemption daily or less often"}]},{"n":"Debt (interval)","c":[{"n":"Sectoral debt: ≥2 sectors, max 75% per sector"},{"n":"Redemption weekly or less often"}]},{"n":"Hybrid (interval)","c":[{"n":"Hybrid Long-Short: ≥25% each in equity and debt"},{"n":"Redemption twice a week or less often"}]}]},{"n":"Industry growth","c":[{"n":"AUM Rs 11.89 lakh cr (Mar 2015) → Rs 82.03 lakh cr (Feb 2026), 19.3% p.a."},{"n":"Folios 4.8 cr (2010) → 27.39 cr (Mar 2026)"},{"n":"Monthly SIP Rs 8,055 cr (2019) → Rs 32,087 cr (Mar 2026)"},{"n":"SIP assets Rs 15.11 lakh cr (Mar 2026)"},{"n":"Household share: MF 10% → 14%; deposits 71% → 65% (2016–18)"}]}]}},{"id":"ch3","n":3,"marks":4,"title":"Legal Structure of Mutual Funds","sub":"Every player in an Indian mutual fund, from SEBI and the sponsor down to CRISIL, CAMS and NMF-II.","root":{"n":"Mutual Fund (a Trust)","c":[{"n":"Legal base","c":[{"n":"SEBI (Mutual Funds) Regulations, 2026"},{"n":"Registration granted under Regulation 3"},{"n":"Indian Trusts Act, 1882 governs the trust"},{"n":"Trust deed registered under Indian Registration Act, 1908"},{"n":"MF = trust raising money by selling units, under one or more schemes","c":[{"n":"Invests in securities, money market, gold, silver and other assets SEBI allows"}]}]},{"n":"Regulators","c":[{"n":"SEBI","c":[{"n":"Registers the mutual fund"},{"n":"Prior approval: trustees, AMC, change in AMC control"},{"n":"Gives observations on SID/SAI (vets, never approves)"},{"n":"Complaints via SCORES"}]},{"n":"RBI","c":[{"n":"Money market, forex, overseas investment rules"}]},{"n":"Stock exchanges","c":[{"n":"Listing, trading and margin rules for listed units"}]}]},{"n":"Sponsor","c":[{"n":"Creates the trust; main person behind the MF"},{"n":"Applies to SEBI for registration"},{"n":"Invests in the AMC's capital"},{"n":"Eligibility","c":[{"n":"≥ 5 years in financial services"},{"n":"Positive net worth in each of last 5 years"},{"n":"Net profit in each of last 5 years"},{"n":"Average net profit ≥ Rs 10 crore (5 yrs)"},{"n":"Liquid net worth > capital contribution to AMC"},{"n":"Fit and proper; sound track record"}]},{"n":"Must keep AMC net worth ≥ Rs 50 crore at all times"},{"n":"Liability limited to initial contribution"},{"n":"Categories (AMFI): banks, institutions, private sector (Indian, foreign, JV)"}]},{"n":"Trustees","c":[{"n":"Form","c":[{"n":"Individuals = Board of Trustees"},{"n":"Or a Trustee Company (acts via its Board of Directors)"}]},{"n":"Composition","c":[{"n":"At least 2/3 independent directors"},{"n":"Independent = not associate of sponsor, AMC or trustee company"},{"n":"Prior SEBI approval to appoint"}]},{"n":"Eligibility (Regulation 11)","c":[{"n":"Fit and proper (Schedule II, Intermediaries Regulations 2008)"},{"n":"Not a director, officer or employee of an AMC"},{"n":"Not a trustee of another mutual fund"},{"n":"Gives SEBI any information it asks for"}]},{"n":"Duties (6 heads)","c":[{"n":"Appoint and terminate the AMC"},{"n":"Conflicts of interest and broker empanelment"},{"n":"Regulatory compliance"},{"n":"Oversight for investor interests"},{"n":"Additional oversight"},{"n":"Due diligence on matters SEBI specifies"}]},{"n":"Sign Investment Management Agreement with AMC"},{"n":"Appoint custodian and scheme auditor"},{"n":"Can remove AMC by majority (with SEBI + unitholder approval)"}]},{"n":"Asset Management Company (AMC)","c":[{"n":"Appointment and rules","c":[{"n":"Appointed by sponsor or trustees, with SEBI approval"},{"n":"Net worth ≥ Rs 50 crore (from 1 Jan 2024)"},{"n":"≥ 50% directors not associates of sponsor or trustees"},{"n":"Directors: finance experience; fit and proper"},{"n":"Director appointment needs trustee approval"},{"n":"AMC directors (incl. Chairman) can't sit on any MF trustee board"},{"n":"No one can be a director of more than one AMC"},{"n":"Change of control: trustees + SEBI approval","c":[{"n":"Letter to each unitholder"},{"n":"Ads: English national daily + regional language"},{"n":"Exit at NAV, no load, ≥ 30 days"}]},{"n":"Removal: majority of trustees or 75% of unitholders"}]},{"n":"Fund management","c":[{"n":"Analysts: find opportunities"},{"n":"Fund managers: decide; own scheme performance"},{"n":"Dealers: place orders with brokers"}]},{"n":"Compliance Officer","c":[{"n":"Signs due diligence certificate on SID"},{"n":"Reports to AMC head"},{"n":"Flags non-compliance directly to trustees"}]},{"n":"Operations and customer service","c":[{"n":"Front office and back office"},{"n":"RTA liaison: records, allotment, statements"},{"n":"Custody team: settlement with custodian"},{"n":"Fund accounting: books and daily NAV"}]},{"n":"Risk management (SEBI RMF)","c":[{"n":"Investment risk"},{"n":"Compliance risk"},{"n":"Operational risk"},{"n":"Cyber security"}]},{"n":"Sales and marketing","c":[{"n":"Branding, advertising, events"},{"n":"Distributor relationships and training"}]},{"n":"Support functions","c":[{"n":"Finance / Accounts (AMC's own books)"},{"n":"Administration"},{"n":"HRD"},{"n":"IT / technology"}]}]},{"n":"Service providers","c":[{"n":"Custodian","c":[{"n":"Appointed by trustees"},{"n":"SEBI (Custodian) Regulations, 1996"},{"n":"Holds assets; settles trades"},{"n":"Tracks corporate actions: dividend, bonus, rights"},{"n":"Not if sponsor holds ≥ 50% voting rights or directors"}]},{"n":"Registrar and Transfer Agent (RTA)","c":[{"n":"Appointed by AMC; optional (can be in-house)"},{"n":"Must register with SEBI"},{"n":"Folios, purchases, redemptions, account statements"},{"n":"Offices act as Investor Service Centres"},{"n":"CAMS and KFintech (QRTAs; run MITRA)"}]},{"n":"Fund accountant","c":[{"n":"Calculates NAV"},{"n":"No SEBI registration needed; in-house or outsourced"}]},{"n":"Auditors","c":[{"n":"Scheme auditor: appointed by trustees"},{"n":"AMC auditor: appointed by AMC"},{"n":"The two must be different"}]},{"n":"Collecting bankers and payment aggregators","c":[{"n":"Appointed by AMC"},{"n":"Payment gateways, wallets, payment banks"}]},{"n":"KYC Registration Agencies (KRAs)","c":[{"n":"SEBI KRA Regulations, 2011"},{"n":"One KYC across the securities market (PMLA)"},{"n":"Central KYC Records Registry: CERSAI"}]},{"n":"Valuation agencies","c":[{"n":"At least 2, for non-traded or thinly traded debt"},{"n":"CRISIL and ICRA (appointed by AMFI)"},{"n":"AMCs use their valuation level"}]},{"n":"Credit rating agencies","c":[{"n":"CRISIL, ICRA, CARE, India Ratings (Fitch)"},{"n":"Define corporate bond and credit risk funds"},{"n":"FMP: invest only at proposed rating or better"}]},{"n":"Depositories and DPs","c":[{"n":"NSDL and CDSL"},{"n":"DP is like a bank branch; depository like head office"},{"n":"ETF units must be held in demat"}]}]},{"n":"Distribution and platforms","c":[{"n":"Distributors","c":[{"n":"NISM Series V-A + ARN from AMFI"},{"n":"KYD: PAN, address proof, biometrics at CAMS PoS"},{"n":"Employees: EUIN under the firm's ARN"},{"n":"New cadre (limited schemes): NISM V-B"},{"n":"Individuals, banks, NBFCs, brokers, national distributors"},{"n":"Can be empanelled with many AMCs"}]},{"n":"Stock exchange platforms","c":[{"n":"BSE StAR MF"},{"n":"NSE NMF-II"},{"n":"Order routing only; AMC handles settlement"}]},{"n":"MF Utilities (MFU)","c":[{"n":"AMFI industry initiative"},{"n":"One CAN, one form, many AMCs"}]},{"n":"Execution Only Platforms (direct plans)","c":[{"n":"Category 1: AMFI-registered, agent of AMCs"},{"n":"Category 2: SEBI stock broker, agent of investor"}]},{"n":"AMC websites and apps; RTA interoperable platform"}]},{"n":"AMFI","c":[{"n":"Association of all registered AMCs"},{"n":"Issues ARN; can cancel it for code violations"},{"n":"Code of Ethics (AMCs) and AGNI code (distributors)"},{"n":"Investor awareness; represents industry to SEBI, RBI, Govt"},{"n":"Not a regulator, not an SRO"}]},{"n":"Unitholders (investors)","c":[{"n":"Beneficiaries of the trust"},{"n":"Own the scheme's assets proportionately"},{"n":"Can sue trustees, not the trust (notional entity)"},{"n":"75% can remove the AMC or wind up a scheme"}]}]}},{"id":"ch4","n":4,"marks":10,"title":"Legal and Regulatory Framework","sub":"Regulators, SEBI reforms, investment restrictions, the advertisement code, investor rights, grievances and the MFD code of conduct.","root":{"n":"Legal and Regulatory Framework","c":[{"n":"Regulators","c":[{"n":"RBI: banks, money market"},{"n":"SEBI: securities (regulates MFs)"},{"n":"IRDAI: insurance"},{"n":"PFRDA: pension"},{"n":"All under the Ministry of Finance"},{"n":"AMFI is not a regulator"},{"n":"RBI rules also apply: money market, overseas investment, forex"}]},{"n":"SEBI","c":[{"n":"Preamble: protect investors, develop and regulate the market"},{"n":"MF Regulations 1996 → replaced by MF Regulations 2026"},{"n":"\"Securities\" defined in Sec 2(h), SCRA 1956"},{"n":"Reforms","c":[{"n":"Benchmark = Total Return Index (TRI), not Price Return Index"},{"n":"Debt PRC matrix: Macaulay duration × Credit Risk Value (1 Dec 2021)"},{"n":"Segregated portfolio after the 2018 credit crisis"},{"n":"2008 crisis: no premature FMP redemption; \"liquid plus\" name banned"}]}]},{"n":"Investment restrictions","c":[{"n":"Regulation 39: permitted investments","c":[{"n":"Securities, money market instruments"},{"n":"Privately placed debentures"},{"n":"Securitised debt (asset / mortgage backed)"},{"n":"Gold, silver; anything else SEBI specifies"}]},{"n":"Regulation 41","c":[{"n":"Follow the Sixth Schedule (except gold / silver ETFs)"},{"n":"Settle only in demat"},{"n":"No carry-forward deals"},{"n":"Derivatives and short selling only on a recognised exchange"},{"n":"Inter-scheme transfers only on SEBI's conditions"}]},{"n":"Sixth Schedule","c":[{"n":"Equity and debt only if listed or to be listed"},{"n":"Except unlisted G-secs, money market (not CPs), unlisted NCDs as allowed"},{"n":"Unrated debt on SEBI's conditions"}]},{"n":"Fund of funds rules","c":[{"n":"Scheme may invest in another MF scheme with no fees"},{"n":"No scheme can invest in a FoF"},{"n":"FoF can't invest in another FoF; holds only MF units"}]},{"n":"Gold / silver ETFs","c":[{"n":"Only gold / silver or related instruments"},{"n":"May use exchange-traded commodity derivatives"},{"n":"Idle money in short-term bank deposits"}]},{"n":"Delivery basis only; securities held in the MF's name"},{"n":"Idle money: short-term deposits of scheduled commercial banks"},{"n":"SIF (Regulation 51): same instruments as Reg 39 + Sixth Schedule"}]},{"n":"Advertisement code","c":[{"n":"Fifth Schedule of MF Regulations 2026"},{"n":"Banned","c":[{"n":"Testimonials, rankings, celebrities, projections"},{"n":"Unfair comparisons"}]},{"n":"Standard warning","c":[{"n":"\"Mutual Fund investments are subject to market risks, read all scheme related documents carefully.\""},{"n":"No words added or removed"},{"n":"Audio-visual: 14 words, visual + voice-over, ≥5 seconds"},{"n":"Vernacular ad: warning in the vernacular"}]},{"n":"Performance ads","c":[{"n":"<6 months: no performance"},{"n":"6–12 months: simple annualised 6-month return"},{"n":">3 years: CAGR 1, 3, 5 yrs + since inception + Rs 10,000 point-to-point"},{"n":"Say regular or direct"},{"n":"Overnight, liquid, money market: simple annualised 7, 15, 30 days"},{"n":"Same fund manager's schemes; >6 = count + top 3 and bottom 3"}]},{"n":"Additional benchmark","c":[{"n":"Equity, balanced, aggressive, BAF, multi-asset, retirement, children's: Sensex / Nifty"},{"n":"Debt ≤1 yr and arbitrage: 1-yr T-bill"},{"n":"Other debt, conservative hybrid, equity savings: 10-yr GoI"}]},{"n":"IDCW ads","c":[{"n":"Rs per unit + face value + prevailing NAV"},{"n":"Just below: NAV falls by payout and statutory levy"}]},{"n":"Celebrity endorsement","c":[{"n":"Industry level only, prior SEBI approval"},{"n":"Paid from investor education pool; never for a scheme or AMC brand"}]},{"n":"SIF branding","c":[{"n":"Distinct brand, logo, website / page"},{"n":"MF brand for 5 yrs: \"brought to you by\"; MF font no bigger"}]},{"n":"Unverified market news: only after Compliance Officer approval"}]},{"n":"Investor rights","c":[{"n":"Ownership","c":[{"n":"Proportionate beneficial ownership"},{"n":"Unit certificate or demat; demat freely transferable (except ELSS lock-in)"},{"n":"Can pledge units"},{"n":"Up to 10 nominees; no % = equal split"}]},{"n":"Switch distributor or go direct: written request, no NOC"},{"n":"Can inspect: Trust Deed, IMA, Custodial and RTA agreements, AMC Memorandum & Articles"},{"n":"Fundamental attribute change","c":[{"n":"Written communication (email / SMS) + AMC website"},{"n":"Exit at NAV, no load, ≥30 days"}]},{"n":"75% of unitholders can remove the AMC or wind up a scheme"},{"n":"Sue the trustees, not the trust (notional entity)"},{"n":"Caveat emptor; prospective investor has no such rights"},{"n":"Unclaimed money","c":[{"n":"Within 3 yrs: prevailing NAV"},{"n":"After 3 yrs: NAV at end of year 3"},{"n":"Separate liquid plan; max fee 0.50% p.a.; no exit load"}]},{"n":"Debt trades disclosed daily, 15-day lag"},{"n":"Recovered illiquid security: within 2 yrs to old investors, else Investor Education Fund"},{"n":"Complaint status: annual report, MF site, AMFI site"}]},{"n":"Grievances and codes","c":[{"n":"AMC resolves complaints in 21 calendar days"},{"n":"SCORES: SEBI's online system; physical complaints scanned and uploaded"},{"n":"Cyber framework CSCRF (CERT-In): Anticipate, Withstand, Contain, Recover, Evolve"},{"n":"Fourth Schedule: SEBI code for AMCs and trustees"},{"n":"AMFI Code of Ethics (ACE): higher, more explicit standards"},{"n":"AGNI: AMFI Guidelines & Norms for Intermediaries"},{"n":"Breach process","c":[{"n":"Explanation within 3 weeks"},{"n":"Warning letter"},{"n":"2nd proven violation: ARN cancelled, all AMCs told"},{"n":"Appeal to AMFI allowed"}]}]},{"n":"MFD code (Appendix 3)","c":[{"n":"Fiduciary: investor's interest is paramount"},{"n":"Never","c":[{"n":"Rebates or pass-back, gifts, inducements"},{"n":"Churning or splitting applications"},{"n":"Indicative portfolio, yield or assured returns"},{"n":"Own contact details on a client form"},{"n":"Deal in direct plans"},{"n":"Share client data with group companies for cross-selling"},{"n":"Call yourself adviser, wealth manager, consultant (unless SEBI RIA)"}]},{"n":"Always","c":[{"n":"Disclose all commissions and group conflicts"},{"n":"Add the EUIN"},{"n":"Use AMC-provided material; logo only with written approval"},{"n":"Check suitability: financial status, experience, objectives"},{"n":"Sub-distributors hold a valid ARN"},{"n":"Refund clawback commissions"},{"n":"Report moral turpitude or arrest to AMC and AMFI"},{"n":"Tagline \"AMFI-registered Mutual Fund Distributor\", font ≥12"}]}]}]}},{"id":"ch5","n":5,"marks":10,"title":"Scheme Related Information","sub":"SID, SAI and KIM, fundamental attributes, update deadlines and every disclosure: NAV, TER, risk-o-meter, portfolio, results and reports.","root":{"n":"Scheme Related Information","c":[{"n":"Mandatory documents","c":[{"n":"Scheme related documents = SID + SAI (+ KIM)"},{"n":"Caveat emptor: investor presumed to have read them"},{"n":"SEBI format, same sequence; SEBI vets with observations, never approves"},{"n":"Drafts on SEBI site; finals on AMFI and MF sites"},{"n":"Contract: offer = documents; acceptance = form + payment; completes on allotment"}]},{"n":"SID","c":[{"n":"Details of one scheme"},{"n":"Cover page: name, type, face value, NFO dates, AMC and trustee"},{"n":"Disclaimer: AMC Due Diligence Certificate; SEBI hasn't approved it"},{"n":"Risk-o-meter + suitability on front page"},{"n":"Standard risks: sponsor not liable beyond initial contribution"},{"n":"Eligible investors: NFO and Ongoing Offer section"},{"n":"Objective can be primary + secondary"}]},{"n":"SAI","c":[{"n":"Statutory info on the MF / AMC; one SAI for all schemes"},{"n":"Legally part of the SID"},{"n":"Constituents, condensed financials (last 3 FYs), valuation norms"},{"n":"How to apply, modes of transaction, nomination, pledge, tax"},{"n":"Printed copy on request; all SAIs on AMFI site"}]},{"n":"KIM and addendum","c":[{"n":"KIM = summary of SID + SAI"},{"n":"Every application form must carry a KIM"},{"n":"Performance 1, 3, 5 yrs and since inception"},{"n":"Addendum = interim change; part of the documents; goes with KIM"}]},{"n":"Fundamental attributes","c":[{"n":"Type of scheme"},{"n":"Investment objective + min / max asset allocation"},{"n":"Terms of issue: liquidity, fees and expenses, safety net"},{"n":"To change (Reg 22(9)(c))","c":[{"n":"Written communication (email / SMS) to each unitholder"},{"n":"Details on AMC website"},{"n":"Exit at prevailing NAV, no exit load"}]}]},{"n":"Update timelines","c":[{"n":"SID: within 6 months of launch half-year; then 1 month after each half-year"},{"n":"Fundamental change: addendum now; SID revised after ≥30-day exit window"},{"n":"Other changes: addendum to website, distributors and ISCs"},{"n":"SAI: within 3 months of FY end"},{"n":"KIM: every half-year, within 1 month; filed electronically"}]},{"n":"NAV and expense disclosure","c":[{"n":"NAV every business day on AMC and AMFI sites"},{"n":"Liquid and overnight: also Sundays and holidays"},{"n":"Close-ended: at least weekly"},{"n":"TER daily (except IDFs), Format 7E, machine-readable"},{"n":"TER = BER + brokerage + transaction cost + statutory levies"},{"n":"BER under Regulation 66(7); direct plan BER lower"},{"n":"BER change: email / SMS + website ≥3 working days before"},{"n":"Expense item >10% of total disclosed in accounts"},{"n":"Scheme dashboard: AUM, TER, manager, benchmark, exit load, portfolio"}]},{"n":"Risk-o-meter","c":[{"n":"6 levels","c":[{"n":"Low: Irish Green"},{"n":"Low to Moderate: Chartreuse"},{"n":"Moderate: Neon Yellow"},{"n":"Moderately High: Caramel"},{"n":"High: Dark Orange"},{"n":"Very High: Red"}]},{"n":"Reviewed monthly; change = notice-cum-addendum + email / SMS"},{"n":"Scheme and benchmark risk-o-meter shown together"},{"n":"Commodity score (15-yr annualised volatility, quarterly)","c":[{"n":"<10% = 3"},{"n":"10–15% = 4"},{"n":"15–20% = 5"},{"n":">20% = 6"}]},{"n":"Only a first step, not the sole basis for decisions"},{"n":"SIF Risk-Band: 5 levels, set at NFO, monthly, published in 10 days"}]},{"n":"Portfolio and reports","c":[{"n":"Portfolio: monthly and half-yearly, with ISIN, within 10 days"},{"n":"Debt schemes: fortnightly, within 5 days, plus yield"},{"n":"SIF: every alternate month, within 10 days; ISID has scenario analysis"},{"n":"Unaudited half-yearly results: within 1 month, email / SMS to unitholders"},{"n":"Annual report: within 4 months; ad in English + Hindi dailies"},{"n":"Factsheet: voluntary; monthly is AMFI best practice"},{"n":"Derivatives only to hedge, no open positions"}]}]}},{"id":"ch6","n":6,"marks":6,"title":"Fund Distribution and Channel Management","sub":"Channels, transaction platforms, becoming a distributor, trail commission, disclosure and due diligence, nomination and change of distributor.","root":{"n":"Fund Distribution and Channel Management","c":[{"n":"Channels","c":[{"n":"Distributor analyses the investor; fund manager analyses the market"},{"n":"Individuals, banks, national / regional distributors, NBFCs, brokers, post offices, direct, online"},{"n":"LIC and UTI built the individual agent force"},{"n":"Employee model = fixed cost; sub-agent model = variable cost"},{"n":"Multinational banks entered first; PSU banks give non-urban reach"},{"n":"Distribution companies and banks = institutional distributors"}]},{"n":"Platforms","c":[{"n":"Paper forms: OPOAs"},{"n":"Stock exchanges: NSE NMF-II, BSE StAR MF","c":[{"n":"AMFI-registered trading members signed up with the MF"},{"n":"Limited purpose membership for distributors"},{"n":"DPs can only process redemptions"},{"n":"Order routing only: don't replace RTAs; AMC settles"},{"n":"Investors can use directly (26 Feb 2020)"},{"n":"SIP, STP, SWP, switch; units to demat"}]},{"n":"MF Utilities","c":[{"n":"CAN needs KYC; investor may hold several"},{"n":"One form, one payment, many schemes"},{"n":"MFU bank / nomination overrides folio"}]},{"n":"RTA interoperable platform: since 31 Dec 2021"},{"n":"MFCentral (CAMS + KFintech)","c":[{"n":"Consolidated view of demat + non-demat folios"},{"n":"Service requests and transactions"},{"n":"CAS, unclaimed amounts, family portfolio"}]},{"n":"New-age apps (Groww, Kuvera, Paytm Money, Coin): direct plans too"}]},{"n":"Becoming a distributor","c":[{"n":"NISM V-A","c":[{"n":"CPE exemption: age ≥50 or ≥10 yrs experience on 31 May 2010"}]},{"n":"KYD: PAN + address proof at CAMS PoS, right index finger"},{"n":"New cadre (V-B) exempt from KYD biometrics"},{"n":"ARN: minimum age 18; online only from 1 Oct 2024"},{"n":"Employees: EUIN under firm's ARN"},{"n":"Empanelment: compulsory, no standard form, AMC can end anytime"}]},{"n":"Commission","c":[{"n":"Full trail only (Master Circular 20 Mar 2026)","c":[{"n":"No upfront; no upfronting of trail; monetary only"},{"n":"AMC pays (Regulation 66(6))"}]},{"n":"Trail on daily net assets, paid monthly or quarterly"},{"n":"Daily trail = AUM × rate ÷ 365 (Rs 10 lakh at 1% = Rs 27.40)"},{"n":"No commission on self-investment"},{"n":"Transaction charges withdrawn (Aug 2025)"},{"n":"Additional commission (Nov 2025)","c":[{"n":"New PAN from B-30, or new women investors (Top 30 + B-30)"},{"n":"Lump sum: 1%, max Rs 2,000, if held ≥1 yr"},{"n":"SIP: 1% of first year, max Rs 2,000"},{"n":"From 2 bps investor education pool; clawback; no dual incentive"}]},{"n":"GST","c":[{"n":"From July 2017; threshold Rs 20 lakh"},{"n":"Unregistered distributor: recipient pays (reverse charge)"}]}]},{"n":"Disclosure and due diligence","c":[{"n":"Trigger (any one)","c":[{"n":">20 locations"},{"n":">Rs 100 cr AUM (non-institutional)"},{"n":">Rs 1 cr commission a year"},{"n":">Rs 50 lakh from one AMC"}]},{"n":"Yearly: inflows, average AUM, AUM / gross inflows, sponsor associate?"},{"n":"Turnover >2× industry average: extra due diligence"},{"n":"Checks: business model, penalties, associates, suitability separate from sales"}]},{"n":"Advisory vs execution only","c":[{"n":"Advice is incidental to distribution: no RIA needed"},{"n":"Can't call himself adviser or planner"},{"n":"Only two types: advisory or execution only"},{"n":"Unsuitable + execution only: written warning + written confirmation"},{"n":"Mis-selling under PFUTP 2003"}]},{"n":"Distributor nomination","c":[{"n":"Commission to nominee until ARN change or AUM nil"},{"n":"Nominee needs no ARN; receives as trustee for legal heirs"},{"n":"ARN valid on date of death; no new business or SIPs"},{"n":"AUM transfer: valid ARN + KYD; clients told; 15 days to object"}]},{"n":"Change of distributor","c":[{"n":"Investor change: no commission to either (unless old ceased business)"},{"n":"New distributor may get trail after 12-month cooling-off"},{"n":"Distributor-initiated only for","c":[{"n":"Name / legal status change"},{"n":"Merger / acquisition within group"},{"n":"Family AUM consolidation"},{"n":"Transfer of business"},{"n":"Entire AUM, valid KYD ARN, old ARN surrendered"}]}]}]}},{"id":"ch7","n":7,"marks":8,"title":"NAV, TER and Pricing of Units","sub":"Valuation principles, the NAV formula, every TER slab, AT1/AT2 limits, IDCW rules, loads and segregated portfolios.","root":{"n":"NAV, TER and Pricing of Units","c":[{"n":"Valuation","c":[{"n":"Seventh Schedule; aim = fair to entering, exiting, staying investors"},{"n":"10 principles; they prevail over the Guidelines"},{"n":"Principle 1: realisable value, in good faith"},{"n":"Policy","c":[{"n":"Approved by AMC Board; new security type needs a method first"},{"n":"Independent auditor review at least yearly"},{"n":"Disclosed in SAI and website"},{"n":"AMC responsible; may deviate (report to Boards, tell investors)"}]},{"n":"Traded equity: last close on principal exchange"},{"n":"Not traded today: other exchange or previous day within 30 days"},{"n":"Non-traded (no trade 30 days)","c":[{"n":"Good faith, AMC Board methods; trustees review"},{"n":"Earnings capitalisation ± book value, less illiquidity discount"}]},{"n":"Convertibles: debt and equity parts separately"},{"n":"Warrants: share value − exercise price − discount"},{"n":"Debt: trade prices from all public platforms"},{"n":"Gold ETF: LBMA AM fixing, 995.0 fineness"},{"n":"Silver ETF: LBMA AM fixing, 999.0 fineness"}]},{"n":"NAV","c":[{"n":"NAV = net assets ÷ units outstanding"},{"n":"Net assets = total assets − liabilities other than to unitholders"},{"n":"Example: Rs 217 cr ÷ 20 cr units = Rs 10.85"},{"n":"Includes unrealised gains"},{"n":"Accrual principle: count when due, not when paid"},{"n":"Short-term borrowing for liquidity ≤6 months"},{"n":"Mark to market stops dilution","c":[{"n":"Issue below NAV lowers NAV for existing investors"},{"n":"Redeem below NAV raises it"}]}]},{"n":"Expenses and TER","c":[{"n":"All expenses paid from the scheme, within base limits"},{"n":"Allowed: distribution, brokerage, RTA, trustee, audit, custodian, insurance, listing, storage of gold / silver"},{"n":"Above limits: borne by AMC, trustees or sponsor"},{"n":"Equity-oriented for TER: ≥65% equity"},{"n":"Open-ended slabs (equity / other)","c":[{"n":"First Rs 500 cr: 2.10 / 1.85"},{"n":"Next 250: 1.90 / 1.65"},{"n":"Next 1,250: 1.60 / 1.40"},{"n":"Next 3,000: 1.50 / 1.25"},{"n":"Next 5,000: 1.40 / 1.15"},{"n":"Next 40,000: −0.05% per Rs 5,000 cr"},{"n":"Balance: 0.95 / 0.70"}]},{"n":"Index fund / ETF: ≤0.90%"},{"n":"FoF","c":[{"n":"Into liquid / index / ETF: 0.90%"},{"n":"≥65% in equity schemes: 2.10%"},{"n":"Others: 1.85%"},{"n":"Own layer ≤2× underlying TER"}]},{"n":"Close-ended / interval: equity 1.00%, others 0.80%"},{"n":"Brokerage on top: ≤0.06% cash, ≤0.02% derivatives"},{"n":"Total = base + brokerage + transaction cost + levies; nothing else but exit load"},{"n":"Old extra 0.05% for exit-load schemes: gone"}]},{"n":"AT1 and AT2 bonds","c":[{"n":"MF ≤10% of one issuer's bonds"},{"n":"Scheme ≤10% of assets; ≤5% in one issuer"},{"n":"AT1 deemed maturity: 100 yrs from issue"},{"n":"AT2: contractual maturity"},{"n":"AT1 valued on yield to call"},{"n":"Close-ended debt schemes can't buy perpetuals"}]},{"n":"IDCW","c":[{"n":"Only from distributable surplus","c":[{"n":"Valuation gains ignored"},{"n":"Valuation losses deducted"}]},{"n":"Trustees decide amount and record date"},{"n":"Monthly-or-more payouts can be delegated to AMC officials"},{"n":"Notice within 1 day; record date 5 calendar days later"},{"n":"No notice for daily-to-monthly payouts in liquid / debt"},{"n":"Late payment: interest from record date"},{"n":"May include capital (equalisation reserve); split disclosed"}]},{"n":"Loads and pricing","c":[{"n":"Entry load banned: sale price = NAV (+ stamp duty)"},{"n":"Exit load: price = NAV × (1 − load)","c":[{"n":"Rs 11 with 1% load = Rs 10.89"}]},{"n":"No distinction by amount; changes only prospective"},{"n":"None on bonus or IDCW-reinvestment units"},{"n":"Credited back to the scheme"},{"n":"Rs 25,000 at NAV 43.21 = 578.570 units"}]},{"n":"Accounting","c":[{"n":"Scheme accounts separate from AMC, different auditors"},{"n":"NAV decimals: 4 for index, liquid, debt; ≥2 for equity, balanced"},{"n":"Fractional units allowed; exchanges trade whole units"},{"n":"Segregated portfolio","c":[{"n":"No management fee"},{"n":"Other TER only pro-rata on recovery"},{"n":"NAV declared daily"},{"n":"Unrated debt: only on actual default"}]}]}]}},{"id":"ch8","n":8,"marks":4,"title":"Taxation","sub":"What decides the tax, the rate table, grandfathering, IDCW, stamp duty and STT, loss set-off, ELSS, TDS and GST.","root":{"n":"Taxation","c":[{"n":"Scheme and options","c":[{"n":"Scheme income exempt: Sec 10(23D), MFs are trusts"},{"n":"Growth: capital gains only"},{"n":"IDCW: dividend + capital gains"},{"n":"Joint holding: taxed in first holder's hands"}]},{"n":"What decides the tax","c":[{"n":"Type of income, holding period"},{"n":"Type of scheme, type of investor"},{"n":"Purchase date (1 Apr 2023) and redemption date (23 Jul 2024)"},{"n":"Equity-oriented for tax: >65% listed Indian equity"},{"n":"FoF in equity MFs = non-equity"},{"n":"Holding periods: 12 months (listed, equity funds) or 24 months"}]},{"n":"Tax rates (STCG / LTCG)","c":[{"n":"Equity-oriented (incl. hybrid >65% equity)","c":[{"n":"20% / 12.5% after 12 months"},{"n":"Rs 1.25 lakh LTCG exempt per FY"}]},{"n":"Debt-oriented (hybrid >65% debt): slab rate"},{"n":"Hybrid 35–65% equity: slab / 12.5% after 24 months"},{"n":"Other MFs (FoFs, international): slab / 12.5% after 24 months"},{"n":"Equity and Gold ETFs: slab / 12.5% after 12 months (as printed)"},{"n":"Debt ETFs: slab rate"},{"n":"Exemption examples","c":[{"n":"Rs 90,000 gain: no tax"},{"n":"Rs 1.35 lakh gain: tax on Rs 10,000"}]},{"n":"Grandfathering","c":[{"n":"Gains up to 31 Jan 2018 exempt"},{"n":"Cost = higher of actual cost or 31 Jan 2018 NAV"},{"n":"Cost 1 lakh, Jan-18 value 2 lakh: sold 1.8 lakh = 0; 2.2 lakh = Rs 20,000"}]}]},{"n":"IDCW","c":[{"n":"DDT abolished (Budget Feb 2020)"},{"n":"From April 2020: taxed at investor's slab"},{"n":"Tax-exempt investors pay nil"},{"n":"IDCW cuts NAV by more than the post-tax receipt"},{"n":"Growth more tax-efficient: deferral"},{"n":"From 1 Apr 2021: split into income and capital distribution"}]},{"n":"Stamp duty and STT","c":[{"n":"Stamp duty (1 Jul 2020)","c":[{"n":"0.005% on issue: purchase, SIP, STP, switch-in, reinvestment"},{"n":"0.015% on transfer"},{"n":"Units allotted after stamp duty"}]},{"n":"STT","c":[{"n":"Only equity-oriented funds, on sale / redemption"},{"n":"None on purchase; none on debt funds"},{"n":"Redemption to MF: 0.001%"},{"n":"Exchange delivery sale: 0.001%"},{"n":"Non-delivery: 0.025%"},{"n":"Paid by the seller"}]}]},{"n":"Losses","c":[{"n":"No set-off against salary or other heads"},{"n":"STCL against STCG or LTCG"},{"n":"LTCL only against LTCG"},{"n":"Carry forward up to 8 years"},{"n":"Bonus stripping","c":[{"n":"Bought ≤3 months before record date, sold ≤9 months after"},{"n":"Loss disallowed; becomes cost of bonus units"}]}]},{"n":"ELSS (Tax Saver)","c":[{"n":"80C up to Rs 1.5 lakh (individual / HUF)"},{"n":"Old Tax Regime only"},{"n":"3-year lock-in from each SIP and each reinvestment"},{"n":"Benefit to the first holder"},{"n":"New regime: just an equity fund with lock-in"},{"n":"Old retirement funds: 80C with 5-year lock-in"}]},{"n":"TDS","c":[{"n":"No TDS on redemption for residents"},{"n":"IDCW to residents: 10% if > Rs 10,000 a year"},{"n":"NRIs: lower of Income Tax Act or DTAA rate"}]},{"n":"GST and expenses","c":[{"n":"GST on management fee: over and above TER"},{"n":"GST on other fees, brokerage: within TER"},{"n":"From 1 Apr 2026: BER + brokerage + statutory levies"},{"n":"GST on exit load deducted from the load"},{"n":"GST on distributor commission can't hit the scheme"}]}]}},{"id":"ch9","n":9,"marks":15,"title":"Investor Services","sub":"NFOs, plans and options, who can invest, payments, cut-off times, KYC, SIP/SWP/STP, nomination, transmission and service timelines.","root":{"n":"Investor Services","c":[{"n":"NFO and plans","c":[{"n":"Idea from CIO (objective) and CMO (market interest)"},{"n":"SID approved by trustees + AMC Board, filed with SEBI"},{"n":"NFO open min 3 working days, max 15 days (ELSS exempt)"},{"n":"Allot or refund in 5 business days; late = 15% p.a., paid by AMC"},{"n":"Open-ended re-opens within 5 business days of allotment"},{"n":"NFO price Rs 10: units = amount ÷ 10"},{"n":"Demat credit 2 working days; SoA 5 business days"},{"n":"ASBA: money only blocked, debited on allotment"},{"n":"Trustees can reject any application without reason"},{"n":"Direct vs Regular","c":[{"n":"Direct: lower TER, no commission, separate NAV"},{"n":"Write \"Direct\" in the ARN box"},{"n":"Only these two plans can differ by expense"}]},{"n":"SIF: Rs 10 lakh minimum at PAN level"}]},{"n":"Options and bonus","c":[{"n":"IDCW payout","c":[{"n":"Cash to bank, units unchanged"},{"n":"NAV falls to ex-dividend NAV"},{"n":"Cum-dividend NAV: between announcement and payout"}]},{"n":"IDCW reinvestment","c":[{"n":"Units at ex-dividend NAV: Rs 2 × 100 units at NAV 20 = 10 units"},{"n":"Still taxed at slab in the year"}]},{"n":"Growth: no dividend, NAV holds all gains"},{"n":"Workbook: NAV 10 → 12, Re 1 dividend, reinvest at 11 = 9.09 units"},{"n":"Bonus 1:3: 1 free per 3 held; NAV falls, value unchanged"}]},{"n":"Investors and the form","c":[{"n":"Individuals: up to 3 joint holders"},{"n":"Minors: guardian (natural or court-appointed); no joint holders"},{"n":"HUF via the Karta"},{"n":"NRI / PIO / OCI: repatriable or non-repatriable"},{"n":"QFI: FATF member + IOSCO MMOU signatory"},{"n":"FPI: direct (demat) or indirect (UCR)"},{"n":"First holder gets all benefits"},{"n":"PoA holder can do all except nominate"},{"n":"Joint holders can't be added; deleted only on death"},{"n":"KYC address overrides the form"},{"n":"First holder's bank details mandatory"},{"n":"Demat applicants: details match DP; payout to demat bank account"},{"n":"Nomination: opt in or opt out; optional for joint folios"}]},{"n":"Payments","c":[{"n":"Modes","c":[{"n":"NACH (NPCI) replaced ECS"},{"n":"UPI via VPA; AEPS via Aadhaar + fingerprint; USSD *99#"},{"n":"OTM: folio level, on NACH, 3–4 weeks to register"},{"n":"Credit cards not allowed"}]},{"n":"Limits","c":[{"n":"E-wallet + cash: Rs 50,000 per investor per MF per FY"},{"n":"Cash only for resident individuals, sole proprietors, minors"}]},{"n":"Cheques: not post-dated (except SIP), not stale (>3 months), local / at-par"},{"n":"NRI: repatriable from NRE / FCNR; non-repatriable also NRO"},{"n":"Third-party: only 3 exceptions","c":[{"n":"Parent / relative for a minor, up to Rs 50,000"},{"n":"Employer payroll"},{"n":"Custodian for FPI"}]},{"n":"Bank accounts: 5 individuals, 10 non-individuals; one default"},{"n":"Instant Access: liquid / overnight; lower of Rs 50,000 or 90% per day"},{"n":"Redemption by amount or units, FIFO; demat via DP"},{"n":"Two-factor authentication mandatory; broker pool accounts gone"}]},{"n":"Cut-off times","c":[{"n":"Equity and debt purchase: 3 pm, NAV of day funds available"},{"n":"Liquid / overnight purchase: 1:30 pm, NAV of day before receipt"},{"n":"Equity / debt redemption: 3 pm, same day; after = next day"},{"n":"Liquid redemption: 3 pm, NAV of day before next business day"},{"n":"Overnight redemption: 3 pm; online 7 pm"},{"n":"Not for NFOs and international schemes"},{"n":"Time stamp at OPoA; tamper-proof machines; web server time online"}]},{"n":"KYC","c":[{"n":"Everyone: joint holders, NRIs, PoA holder, guardian (not minor)"},{"n":"PAN exempt","c":[{"n":"Govt and court officials, Sikkim residents, UN bodies"},{"n":"Micro-SIP + lump sum ≤ Rs 50,000 a year (PEKRN)"}]},{"n":"KRA: one KYC across market; IPV mandatory"},{"n":"CERSAI: Central KYC Records Registry; KYC Identifier"},{"n":"Aadhaar e-KYC via KUA / sub-KUA"},{"n":"Online: eSign, DigiLocker, OTP, penny drop"},{"n":"UBO","c":[{"n":"Company >25%"},{"n":"Partnership >15%"},{"n":"Trust ≥15% + settlor + trustees"},{"n":"Not for listed companies"}]},{"n":"FATCA / CRS change within 30 days"}]},{"n":"Systematic transactions","c":[{"n":"SIP = rupee cost averaging; average cost below average NAV"},{"n":"SWP: 1% load at NAV 10 = 101.0101 units for Rs 1,000"},{"n":"STP = SWP from source + SIP into target","c":[{"n":"Scheme minimums don't apply; loads and tax do"},{"n":"0.25% load on Rs 1 lakh = Rs 99,750"}]},{"n":"DTP: needs IDCW option; invested next business day after record date"},{"n":"SIP registration 15–30 days"},{"n":"Top-up: +Rs 500 = 3,000 then 3,500; +10% = 2,750 then 3,025"},{"n":"Minor's SIP only till majority"},{"n":"Triggers are one-time: stop-loss, appreciation, date, market level"}]},{"n":"Non-financial transactions","c":[{"n":"Nomination","c":[{"n":"Up to 10 nominees; % totals 100 or equal split"},{"n":"Only individuals; not minor's folio or PoA holder"},{"n":"Nominee: individual (even minor / NRI), govt body, religious / charitable trust"},{"n":"Not: other trusts, society, company, firm, Karta"},{"n":"Nominee holds in trust for legal heirs"},{"n":"Demat follows demat nomination"}]},{"n":"Pledge: all sign, out of lock-in, pledgee's NOC to sell"},{"n":"Changes","c":[{"n":"Name, address, PAN, contact: via KRA"},{"n":"Bank, holding mode, nomination: each MF"},{"n":"Guardian change: new KYC + old guardian's NOC"}]},{"n":"Transmission","c":[{"n":"Joint holder dies: survivor by name deletion, as owner"},{"n":"Single holder: nominee; no nominee: legal heirs"},{"n":"Needs KYC, death certificate, indemnity"}]},{"n":"Minor turns major","c":[{"n":"Folio frozen; SIP / SWP / STP stop"},{"n":"MAM form: PAN, KYC, bank proof, attested signature"},{"n":"New demat account needed"}]},{"n":"NRI returns: resident account (RFC), new demat, update KRA"},{"n":"Change of Karta: indemnity from all co-parceners"}]},{"n":"Statements and service levels","c":[{"n":"SoA each month with a transaction"},{"n":"No transaction in 6 months: annual statement"},{"n":"CAS monthly with a transaction; half-yearly if none; matched by PAN"},{"n":"Unit certificate in 5 working days"},{"n":"Portfolio statement within 10 days of half-year"},{"n":"Delay interest borne by the AMC"},{"n":"MITRA: tracing inactive / unclaimed folios (CAMS + KFintech)"},{"n":"DigiLocker holds MF statements, with nominee access"},{"n":"Voluntary debit freeze (Mar 2026), first on MF Central"}]}]}},{"id":"ch10","n":10,"marks":7,"title":"Risk, Return and Performance of Funds","sub":"Risk factors, what drives equity and debt returns, return maths, risk measures, credit events, gating and side-pocketing.","root":{"n":"Risk, Return and Performance of Funds","c":[{"n":"Risk factors in the SID","c":[{"n":"Standard","c":[{"n":"Past performance no guarantee"},{"n":"Name says nothing about quality"},{"n":"Sponsor liable only to initial contribution"}]},{"n":"General","c":[{"n":"Liquidity, interest rate, reinvestment"},{"n":"Political, economic, foreign currency (AMC doesn't manage)"},{"n":"Settlement / counterparty, exchange transactions"}]},{"n":"Equity and derivatives","c":[{"n":"Large → mid → small: more volatility and liquidity risk"},{"n":"Derivatives are leveraged"},{"n":"Counterparty, market liquidity, model, basis risk"},{"n":"Short selling: counterparty + illiquid borrowed stock"},{"n":"Securities lending: counterparty failure"}]},{"n":"Debt","c":[{"n":"Rating migration: AAA → AA+ = price falls"},{"n":"Reinvestment, term structure, credit"},{"n":"Floaters: spread and basis risk"},{"n":"Corporate bond repo: counterparty risk, cut by over-collateralisation"},{"n":"Money market: liquid but thin secondary market"}]},{"n":"Securitisation","c":[{"n":"Originator sells to an SPV (trust), which issues PTCs"},{"n":"Lower LTV safer; more seasoning better; DPD buckets"},{"n":"Credit enhancement: rated above originator; non-recourse"},{"n":"Risks: prepayment, originator bankruptcy, co-mingling"},{"n":"MFs mostly buy AA and above"}]}]},{"n":"Systematic vs unsystematic","c":[{"n":"Systematic = market, non-diversifiable (inflation)"},{"n":"Unsystematic = company-specific, diversifiable (a strike)"},{"n":"Investors rewarded only for systematic risk"},{"n":"Manager can cut it only by holding cash"}]},{"n":"Equity returns","c":[{"n":"Security selection and market timing"},{"n":"Fundamental: long term; technical (\"chartists\"): short term"},{"n":"Ratios","c":[{"n":"EPS = PAT ÷ shares"},{"n":"P/E = price ÷ EPS; forward P/E uses projected EPS"},{"n":"PEG: 1 fair, <1 cheap, >1 expensive"},{"n":"P/BV = price ÷ book value per share"},{"n":"Dividend yield = DPS ÷ price; falls in bull markets"}]},{"n":"Growth stocks: high P/E, low yield, fall more"},{"n":"Value stocks: below intrinsic value, long horizon"},{"n":"EIC: Economy, Industry, Company"},{"n":"Top-down (economy first) vs bottom-up (stock first)"}]},{"n":"Debt, gold and real estate returns","c":[{"n":"Debt: interest rates and credit spreads"},{"n":"Instruments","c":[{"n":"T-bills: RBI for GoI"},{"n":"CDs: banks 7 days–1 yr; FIs 1–3 yrs"},{"n":"CP: companies, up to 1 yr"},{"n":"Govt bonds; company debentures"}]},{"n":"Credit spread = corporate − gilt yield"},{"n":"Raters: CRISIL, ICRA, CARE, India Ratings"},{"n":"YTM if held to maturity; HPR = interest + gain / loss"},{"n":"Floater: base + spread, holds value"},{"n":"Rates up: shorten duration or floaters; down: go long"},{"n":"9.5% coupon at 8.5% yield: premium"},{"n":"Gold: global price + rupee (weaker rupee helps); passive"},{"n":"Real estate: local asset; no MF schemes now; REITs growing"}]},{"n":"Measuring returns","c":[{"n":"Simple: 12 → 15 = 25%"},{"n":"Annualised = simple × 12 ÷ months: 5% in 6 m = 10%"},{"n":"CAGR = (end ÷ start)^(1/n) − 1; n = days ÷ 365","c":[{"n":"Rs 1,000 → 4,000 in 2 yrs = 100%"},{"n":"Rs 10,000 at 10% for 3 yrs = 13,310"}]},{"n":"Dividends: reinvestment method at ex-dividend NAV"},{"n":"Investor return ≠ scheme return: loads, taxes, timing"},{"n":"<1 yr absolute; >1 yr CAGR"},{"n":"Rolling returns remove start / end-date bias"},{"n":"No promised returns except assured-return schemes (named guarantor)"}]},{"n":"Risk from the investor's view","c":[{"n":"Low risk ≠ zero risk: credit events in 2018 and 2019"},{"n":"Redemptions raise bad paper share: 5% → 10%"},{"n":"Arbitrage using views: not risk-free"},{"n":"Winding-up schemes listed (Clause 37(d))"},{"n":"Real estate funds less risky than direct property"}]},{"n":"Risk measures","c":[{"n":"Variance: fluctuation vs own average"},{"n":"SD = √variance = total risk; ≥30 observations","c":[{"n":"Annualise: ×√52 weekly, ×√12 monthly, ×√252 daily"}]},{"n":"Beta (CAPM): systematic risk; equity only","c":[{"n":"0.8 moves 8% when market moves 10%"}]},{"n":"Modified duration: rate sensitivity, professionals' measure"},{"n":"WAM: 70% × 4 + 30% × 1 = 3.1 yrs; for lay investors"},{"n":"Credit rating: G-secs and cash have no credit risk"}]},{"n":"Credit events, gating, side-pocketing","c":[{"n":"Credit event = default, delay or downgrade"},{"n":"Gating","c":[{"n":"Only market-wide crises, never one bad security"},{"n":"Max 10 working days in 90 days"},{"n":"AMC Board + trustees; SEBI told at once"},{"n":"First Rs 2 lakh of every redemption paid"}]},{"n":"Segregated portfolio (Dec 2018)","c":[{"n":"Optional; triggered by downgrade"},{"n":"Unrated: only on actual default (7 Nov 2019)"},{"n":"Trustees approve; from credit-event day; press release"},{"n":"Equal units; no subscription or redemption; listed in 10 working days"},{"n":"New investors get main portfolio only"},{"n":"No management fee; TER only on recovery; excess legal cost on AMC"}]},{"n":"Mitigants: hold longer; match holding period to maturity"}]}]}},{"id":"ch11","n":11,"marks":7,"title":"Mutual Fund Scheme Performance","sub":"Benchmark rules and TRI, benchmarks for every category, two-tier benchmarks, Sharpe, Treynor, alpha, information ratio and tracking error.","root":{"n":"Mutual Fund Scheme Performance","c":[{"n":"Benchmark rules","c":[{"n":"Match objective, asset allocation and strategy"},{"n":"Run by an independent agency, transparently"},{"n":"Past returns never a basis"},{"n":"Index fund benchmark = the index it tracks"},{"n":"Chosen by AMC with trustees; in the SID; change justified"}]},{"n":"TRI","c":[{"n":"Since 1 Feb 2018 (was PRI)"},{"n":"Adds dividends / interest"},{"n":"Fewer schemes seem to beat it; gap ~1.5–2.5%"},{"n":"Before TRI existed: composite CAGR"}]},{"n":"Equity benchmarks","c":[{"n":"Depends on type, universe, concentration"},{"n":"Sectoral: e.g. Bankex"},{"n":"Fewer stocks: Sensex 30 / Nifty 50"},{"n":"Multi cap: Nifty 500 Multicap 50:25:25 / BSE 500"},{"n":"Large cap: NIFTY 100 / BSE 100"},{"n":"Large & mid: NIFTY LargeMidcap 250"},{"n":"Mid cap: Midcap 150"},{"n":"Small cap: NIFTY Smallcap 250 / BSE 250 SmallCap"},{"n":"ELSS, flexi cap, dividend yield: NIFTY 500 / BSE 500"}]},{"n":"Debt benchmarks","c":[{"n":"From CRISIL, ICICI Securities, NSE (AMFI-recommended)"},{"n":"I-Bex: Si-Bex 1–3 yrs, Mi-Bex 3–7, Li-Bex >7"},{"n":"Overnight: NIFTY 1D Rate / CRISIL Liquid Overnight"},{"n":"Liquid: NIFTY Liquid A-I / CRISIL Liquid Debt A-I"},{"n":"Money market: Money Market A-I"},{"n":"Ultra short: Ultra Short Duration Debt A-I"},{"n":"Low duration: Low Duration Debt A-I"},{"n":"Short duration: Short Duration Debt A-II"}]},{"n":"Hybrid and other benchmarks","c":[{"n":"Hybrid = blend, e.g. 65% Sensex + 35% I-Bex"},{"n":"Conservative: Hybrid Composite Debt 15:85"},{"n":"Balanced, BAF: 50:50"},{"n":"Aggressive: 65:35"},{"n":"Arbitrage: NIFTY 50 Arbitrage"},{"n":"Gold ETF: price of gold"},{"n":"International: local index (S&P 500, Shanghai Composite)"}]},{"n":"Two-tier benchmarks","c":[{"n":"SEBI Oct 2021, effective 1 Jan 2022"},{"n":"Tier 1 = category; Tier 2 = manager's style"},{"n":"Debt and equity schemes; all TRI"},{"n":"Single benchmark: hybrid / solution, sectoral, index / ETF"},{"n":"FoF: single-fund uses underlying's; multi-fund uses broad index"},{"n":"Debt Tier 1 follows PRC from 1 Apr 2022"}]},{"n":"Performance measures","c":[{"n":"Relative return ignores risk"},{"n":"Sharpe = (Rs − Rf) ÷ SD","c":[{"n":"Total risk; (7 − 5) ÷ 0.5 = 4"},{"n":"Compare like with like"}]},{"n":"Treynor = (Rs − Rf) ÷ Beta","c":[{"n":"Systematic risk; (8 − 5) ÷ 1.2 = 2.5"},{"n":"For diversified equity"}]},{"n":"Alpha = actual − beta-expected return; positive = outperformance"},{"n":"Information Ratio","c":[{"n":"Excess over Tier-1 ÷ SD of excess return"},{"n":"Only mandatory measure; daily on AMC and AMFI sites (Jan 2025)"}]},{"n":"Tracking error = SD of excess returns","c":[{"n":"Index fund: ideally zero"},{"n":"Active fund: lower = more consistent"}]},{"n":"Risk-free rate = T-bill return"},{"n":"\"Calculations are arithmetic; evaluation is an art\""}]},{"n":"Where to find performance","c":[{"n":"SID: updated twice a year"},{"n":"Factsheet: monthly, not mandatory; ad rules apply"},{"n":"Product label: objective, asset class, horizon, risk-o-meter"},{"n":"Discrete annual returns show consistency"},{"n":"AMFI site; Morningstar, Value Research"},{"n":"Macro: high deficit = rates up; oil moves currency"}]}]}},{"id":"ch12","n":12,"marks":15,"title":"Mutual Fund Scheme Selection","sub":"Matching funds to investors, risk ladders across categories, choosing by structure and strategy, picking within a category, options and conduct rules.","root":{"n":"Mutual Fund Scheme Selection","c":[{"n":"Investor fit","c":[{"n":"Step 1: set goals"},{"n":"Step 2: situation and risk appetite (need + ability + willingness)"},{"n":"Growth → equity; income → debt; parking → liquid"},{"n":"Equity needs a long horizon"},{"n":"Age alone is a poor guide; use horizon to each goal"},{"n":"Core and satellite","c":[{"n":"Core: long-term goals (diversified, large, mid cap)"},{"n":"Satellite: sector, long gilt, gold"},{"n":"Moderate investor: 80% core / 20% satellite"}]}]},{"n":"Risk ladders (low → high)","c":[{"n":"Overall: liquid → debt → hybrid → equity"},{"n":"Interest rate: overnight → liquid → ultra-short → low → short → medium → medium-long → long"},{"n":"Credit: gilt → banking & PSU → corporate bond → credit risk"},{"n":"Equity: large → large & mid → multi → mid → small"},{"n":"Concentration: diversified → focused → thematic → sector"},{"n":"Hybrid: arbitrage → conservative → equity savings → dynamic → multi-asset → balanced → aggressive"},{"n":"Product labelling (2013): consult an adviser if unsure"}]},{"n":"Structure and style","c":[{"n":"Passive: no selection risk, low cost, still falls with index"},{"n":"Active: higher cost; must beat benchmark"},{"n":"Index or value for low-risk equity; growth for extra return"},{"n":"Open-ended: liquidity at NAV less load; cash drag, flow pressure"},{"n":"Close-ended: exchange exit at a discount; converges near maturity"},{"n":"Close-ended can hold illiquid or long-gestation stocks"}]},{"n":"Equity choices","c":[{"n":"Focused: riskier than diversified, safer than sector"},{"n":"Sector: timing-dependent, satellite"},{"n":"Thematic (MNC, PSU, infra): between diversified and sector"},{"n":"\"Diversification is protection against ignorance\""},{"n":"Mid / small caps shine in recoveries, fail in downturns"},{"n":"Growth wins in bull markets; value in falls or long periods"},{"n":"International: equity + currency; stronger dollar helps; satellite"}]},{"n":"Debt, hybrid and gold choices","c":[{"n":"FMP: horizon = maturity; check credit; exit via exchange"},{"n":"TMFs replacing FMPs: G-secs, SDLs, AAA PSU; liquid via AMC"},{"n":"Short duration: when rates expected to rise"},{"n":"Liquid: savings-account alternative, up to 91 days"},{"n":"Floater NAV steady; duration-managed funds volatile"},{"n":"Hybrid: judge equity and debt separately"},{"n":"\"Conservative\" refers only to equity allocation"},{"n":"Be cautious with dynamic asset allocation"},{"n":"Gold ETF tracks gold; gold sector fund holds miners (more volatile)"}]},{"n":"Choosing within a category","c":[{"n":"True to label portfolio"},{"n":"Consistent outperformance, downside protection, rolling periods"},{"n":"Look-back","c":[{"n":"Equity ≥5 yrs"},{"n":"Long-term debt ≥3 yrs"},{"n":"Liquid: 7 days, 15 days, 1 month"}]},{"n":"Fund age matters where returns diverge (multi cap)"},{"n":"Size helps large cap; hurts mid cap and sector"},{"n":"Portfolio turnover = lower of buys or sells ÷ avg net assets","c":[{"n":"10,000 ÷ 5,000 = 200%, avg holding 6 months"},{"n":"Judge against style: too short for value"}]},{"n":"Costs matter most in debt and index funds"},{"n":"Star ratings: past only, no predictive power"},{"n":"Target top 3–5 (small categories) or top 10–15%"}]},{"n":"Options","c":[{"n":"IDCW payout: not assured; slab tax"},{"n":"SWP better for regular income (capital gains tax)"},{"n":"IDCW suits only tax-exempt investors"},{"n":"Growth compounds pre-tax"},{"n":"Book gains or losses to set off"}]},{"n":"Do's, don'ts and conduct","c":[{"n":"Do: suitability (PFUTP), stick to allocation, know objective"},{"n":"Do: watch taxes and loads; written, consistent method"},{"n":"Don't chase past performance"},{"n":"Fourth Schedule: equitable treatment of all unitholders"},{"n":"Social media: registered name + number on home page and every video"}]}]}}];
